<script setup lang="ts">
import {ref,watch} from 'vue'
import {api,type Template} from './api'
const props=defineProps<{template?:Template,session:any}>()
const emit=defineEmits<{saved:[any],error:[string]}>()
const levels=[{label:'Scurt',value:'brief'},{label:'Standard',value:'standard'},{label:'Detaliat',value:'detailed'}]
const detail=ref(''),sections=ref<Record<string,string>>({}),busy=ref(false)
watch(()=>props.session,()=>{detail.value=props.session.context?.presentation?.detail||'';sections.value={...(props.session.context?.presentation?.sections||{})}},{immediate:true})
async function save(){busy.value=true;try{const overrides=Object.fromEntries(Object.entries(sections.value).filter(([,v])=>v));emit('saved',await api('sessions/'+props.session.id+'/presentation','POST',{revision:props.session.revision,detail:detail.value,sections:overrides}))}catch(e){emit('error',e instanceof Error?e.message:String(e))}finally{busy.value=false}}
</script>
<template><details v-if="template?.sections.length" class="paper"><summary>Stilul raportului · nivel de detaliu pe secțiuni</summary><p class="muted small">Aceleași date clinice, cu formulările configurate în șablon. Schimbarea stilului nu solicită un nou apel AI și creează o revizie nouă pentru aprobare.</p><label>Nivelul întregului raport<Select aria-label="Nivelul întregului raport" v-model="detail" :options="[{label:'Implicit din șablon',value:''},...levels]" optionLabel="label" optionValue="value" :disabled="session.status==='approved'"/></label><div class="three"><label v-for="s in template.sections" :key="s.id">{{s.parent?'↳ ':''}}{{s.label}}<Select :aria-label="(s.parent?'↳ ':'')+s.label" v-model="sections[s.id]" :options="[{label:'Moștenește',value:''},...levels]" optionLabel="label" optionValue="value" :disabled="session.status==='approved'"/></label></div><Button label="Aplică stilul raportului" @click="save" :loading="busy" :disabled="session.status==='approved'"/><p v-if="session.status==='approved'" class="muted small">Documentul aprobat este blocat.</p><ul v-if="session.result?.presentation?.length" class="plan-limits"><li v-for="p in session.result.presentation" :key="p.section_id">{{p.label}} · {{levels.find(l=>l.value===p.detail)?.label}} · {{p.variant_label||'Formulare de bază'}}{{p.reason==='ambiguous_variants'?' — variante ambigue, verifică șablonul':''}}</li></ul></details></template>
